INSERT INTO himnos (id, title, description, musical_note, paragraphs, chorus, filename)
VALUES
('e0e52894-0bb4-5124-a726-641273fc4783', $a$ÉL HA SIDO FIEL$a$, $a$Día a día Tú has sido fiel, no has cambiado y no$a$, $a$D|Re$a$, $a$[{"id": "feadc331-5ec3-d5ee-eea6-3af1b1bcbcad", "paragraph": "Día a día Tú has sido fiel, no has cambiado\ny no cambiarás\nMaravillado estoy con tu amor porque me\namaste siendo un pecador", "chorusPos": [[0]]}, {"id": "75de8fe2-1b63-032e-a7a1-3aeee24a01c8", "paragraph": "Cuando recuerdo mi vida sin ti, sin\nesperanza en sombras viví\nMás hoy reboso en gracia y perdón, porque\nadoptaste a un vil pecador", "chorusPos": [[1]]}, {"id": "4373f22b-63d9-068d-8181-0e4f26e47a32", "paragraph": "Cuando en prueba te exaltaré,\ny cuando duela en ti confiaré\nPorque conozco tu inmensa bondad y sé\nque nunca me abandonarás", "chorusPos": [[1]]}, {"id": "4f6dc50f-d595-1e28-857e-27a047d7f4ca", "paragraph": "Toda mi vida la pongo a tus pies, has lo\nque quieras con ella mi Rey\nHasta que vuelvas con fe cantaré,\n\"Día a día tú has sido fiel\"", "chorusPos": [[1]]}]$a$::jsonb, $a$[{"choir": "Te alabaré, te glorificaré\nPorque agradecido estoy\npor tu inmenso amor\nTe alabaré, te glorificaré\nPorque tu hijo soy, te alabaré", "id": "7ea5eaf9-7524-e8a3-2574-3e9ad3e03ade"}]$a$::jsonb, $a$ÉL HA SIDO FIEL.json$a$),
('e4d393b2-74fa-ad36-4d43-57efd15579df', $a$FUI HECHO JUSTO$a$, $a$Fui hecho justo sin merecerlo toda mi culpa ya c$a$, $a$G|Sol$a$, $a$[{"id": "049c564e-eeea-f894-5a91-1caa805b336c", "paragraph": "Fui hecho justo sin merecerlo\ntoda mi culpa ya cubierta esta.\nToda mi deuda quedó saldada,\npor la persona del cordero inmortal.", "chorusPos": [[1]]}, {"id": "7abf7533-4b7f-be97-0603-bcaf6191d69f", "paragraph": "Regenerado y transformado,\n          Cambio mi mente y mi forma de actuar.\n          Hoy solo quiero servir a Cristo,\n          Y ser la luz la sal de un claro manantial.", "chorusPos": [[1]]}]$a$::jsonb, $a$[{"choir": "Salvación, camino angosto,\n          Plenitud incomparable don de Dios.\n          Una cruz cubierta en sangre.\n          Fue necesaria para nuestra redención.", "id": "7990fd50-d0b5-b7ab-f402-5fff281110fa"}]$a$::jsonb, $a$Fui Hecho Justo.json$a$),
('c6ce2ee1-8405-29c8-d77b-c86e7baed8a7', $a$VIVIR ES CRISTO$a$, $a$Como recibiré de ti el bien, Y el mal rechazare.$a$, $a$G|Sol$a$, $a$[{"id": "1cbf6275-2cde-4c53-ff41-21e80ddde955", "paragraph": "Como recibiré de ti el bien,\nY el mal rechazare.\nSí se que tú eres Señor\nSoberano y justo.", "chorusPos": [[0]]}, {"id": "e547d2cd-f45f-bcc0-92c2-3b00c26f1099", "paragraph": "Como he de alabarte en bendición\ny olvidarte en dolor.\nSi sé que tienes el control,\nde toda tu creación.", "chorusPos": [[0]]}, {"id": "89d1a1fc-0fcc-09b2-b36e-d4992b43cce5", "paragraph": "Como he de creer en ti al tener, y dudar en la escasez\nSi sé que tú eres siempre fiel, y que nunca cambias.\nComo he de seguir en libertad y huir en la opresión\nSi sé que guardas para mí una eterna posesión.", "chorusPos": [[1]]}, {"id": "9786e116-ebd4-755c-3b11-e049c4c8cdcf", "paragraph": "Como he de confiar en tu bondad y tu gran amor por mí,\nSi enviaste a Jesús en mi lugar a morir en una Cruz.\n//Tu gracia es suficiente//", "chorusPos": [[1]]}, {"id": "e06586a3-a83b-06ba-ab10-dd7a5ec71736", "paragraph": "Fija mis ojos solo en ti en lo eterno, en el\ncielo\nLa aflicción de este mundo jamás se\ncompara con la gloria que ha de venir.\n//Vivir es Cristo, vivir es Cristo//", "chorusPos": [[1], [2]]}]$a$::jsonb, $a$[{"choir": "Bendito sea el nombre del Señor, en todo tiempo\nSe haga tu perfecta voluntad, en mí.\nDaré gloria a tu nombre a través de mi aflicción\nDame tu gracia para ver: que vivir es Cristo.", "id": "0fd6c903-3093-07f6-8677-46bdd6a1b266"}, {"choir": "...VIVIR ES CRISTO", "id": "6082b4b8-4825-4195-dd28-167462478add"}]$a$::jsonb, $a$VIVIR ES CRISTO.json$a$),
('0c41c5ca-9067-4902-9693-a580e7ae55da', $a$EN TI CONFÍA MI CORAZÓN$a$, $a$EN TI CONFÍA MI CORAZÓN    EN TI ...$a$, $a$--$a$, $a$[{"paragraph": "EN TI CONFÍA MI CORAZÓN  \n EN TI SE GOZA MI ALMA  \n MI SER DESCANSA EN TI  \n PUEDO SER FELIZ"}, {"paragraph": "POR QUE SE QUE ESTAS OBRANDO TU PERFECTA VOLUNTAD, \n EN MI VIDA ESTAS OBRANDO TU PERFECTA VOLUNTAD"}]$a$::jsonb, $a$[]$a$::jsonb, $a$EN TI CONFÍA MI CORAZÓN.json$a$),
('be04759c-17e4-44fe-99eb-33b9daa89805', $a$Eran cien ovejas de un rebaño$a$, $a$Eran cien ovejas de un rebaño   e...$a$, $a$--$a$, $a$[{"paragraph": "Eran cien ovejas de un rebaño \n eran cienovejas que el      cuido pero una trade al contarlas todas le faltaba una \n esas misma historia vuevle a repetirse \n pero todavia existe el pastro que por las malñas a buscarlas va \n y cuando las alla las trae al camino , al camino bueno de verdad y vida  \n Las cien ovejas"}]$a$::jsonb, $a$[]$a$::jsonb, $a$Eran cien ovejas de un rebaño.json$a$),
('3eb6faaa-acd7-4c58-ba13-326cec666a0b', $a$Cuan bello es el señor$a$, $a$/Cuan bello    es el señor/   cua...$a$, $a$--$a$, $a$[{"paragraph": "/Cuan bello  \n es el señor/ \n cuan hermoso es el señor, \n hoy le quiero adorar"}, {"paragraph": "la belleza de mi señor,  \n nunca se agotara,  \n La hermosura  \n de mi señor, \n siempre resplandecerá."}]$a$::jsonb, $a$[]$a$::jsonb, $a$Cuan bello es el señor.json$a$),
('137e347b-01cd-4395-9cbc-7db64a5791c4', $a$Digno es el$a$, $a$DIGNO ES EL    (APOCALIPSIS 4:8)...$a$, $a$--$a$, $a$[{"paragraph": "DIGNO ES EL  \n (APOCALIPSIS 4:8)"}, {"paragraph": "/Digno es el cordero Santo; \n Santo, Santo es Él.  \n Levantamos nuestra alabanza, \n al que en el trono está./"}, {"paragraph": "Santo, Santo, Santo, Dios todopoderoso,  \n quien fue quien es y quien vendrá. \n La creación hoy canta y damos gloria a Él,  \n Tu eres digno por siempre y siempre."}, {"paragraph": "Digno es el cordero Santo; \n Santo, Santo es Él.  \n Levantamos nuestra alabanza, \n al que en el trono está."}, {"paragraph": "/Santo, Santo, Santo, Dios todopoderoso,  \n quien fue quien es y quien vendrá. \n La creación hoy canta y damos gloria a Él,  \n Tu eres digno por siempre y siempre./"}]$a$::jsonb, $a$[]$a$::jsonb, $a$Digno es el.json$a$),
('42d2e024-b348-4083-a520-b0aaeffba221', $a$CRISTO ME DIJO QUE VENDRÍA OTRA VEZ$a$, $a$/Cristo me dijo que vendría otra ...$a$, $a$--$a$, $a$[{"paragraph": "/Cristo me dijo que vendría otra vez, que vendría otra vez, que vendría otra vez/"}, {"paragraph": "/Alábale, alábale, alábale de corazón/ \n Yo le estoy, yo le estoy esperando \n Yo le estoy, yo le estoy esperando"}]$a$::jsonb, $a$[]$a$::jsonb, $a$CRISTO ME DIJO QUE VENDRÍA OTRA VEZ.json$a$),
('a87413a1-c0c4-e91e-f290-64d1474265ea', $a$DESDE QUE TE CONOCÍ$a$, $a$Desde que te conocí, desde que viniste a mi Desd$a$, $a$D|Re$a$, $a$[{"id": "0c27cbea-0878-f773-2e87-208f1dba420c", "paragraph": "Desde que te conocí, desde que viniste a mi\nDesde que experimente, tu perdón, tu amor, tu paz.\nAlgo nuevo en mi empezó por tu espíritu de amor.\nEs tu vida cual semilla que brotó en mi corazón.", "chorusPos": [[0]]}, {"id": "4ab0bf36-6381-b734-f632-c8528e56d95c", "paragraph": "¡Qué momento tan feliz!\nQue alegría recibí;\nal tener en mi vida tu presencia celestial.\nSé de dónde vengo sé a dónde voy,\nsé quién soy, porque existo y tu propósito en mí.", "chorusPos": [[1]]}, {"id": "898f1125-9095-9aa3-24c1-01cbe20570d3", "paragraph": "Ahora que vives en mí,\nahora que te puedo oír,\nahora que crece en mí;\ntu persona sin igual\nQuiero dejar que seas tú para que no sea yo;\nEl que manda al que vean pues en mi a ti han de ver.", "chorusPos": [[0]]}, {"id": "93fd7ea7-ff60-01dc-2bb1-14884e8fa895", "paragraph": "Correré hasta alcanzar,\nla corona que darás\nEn el día que regreses y nos lleves al hogar,\nAllí llanto no habrá, la justicia reinará\nDesde el trono santo y justo reinaras.", "chorusPos": [[1]]}]$a$::jsonb, $a$[{"choir": "Quiero amar Oh Cristo,\nquiero dar Oh Cristo,\nquiero ser Oh Cristo como tu\nAl caído levantar al enfermo consolar\nA este mundo que agoniza tu remedio alcanzar", "id": "e2d0c003-e796-06ef-4870-3293f3cc6551"}]$a$::jsonb, $a$DESDE QUE TE CONOCÍ.json$a$),
('79ff68f9-a1b2-4d02-b4fa-40cf78bbfc37', $a$Cuando venga de los cielos el señor $a$, $a$CUANDO VENGA DE LOS CIELOS EL SEÑ...$a$, $a$--$a$, $a$[{"paragraph": "CUANDO VENGA DE LOS CIELOS EL SEÑOR ESTÉS VIVO O ESTE MUERTO \n QUE CUENTA LE VAS A DAR"}, {"paragraph": "AMIGO YA NO PEQUES MAS \n  JESÚS TE DICE VEN A MI RECUERDA QUE ES TU SALVADOR RECUERDA QUE EL MURIÓ POR TI"}, {"paragraph": "OH VIENEN LOS ÁNGELES  \n VIENEN LOS ÁNGELES \n A ALABAR AL REY"}]$a$::jsonb, $a$[]$a$::jsonb, $a$Cuando venga de los cielos el señor .json$a$),
('bb02cd79-874f-a8f9-5523-5e8489470fad', $a$EL MISMO AMOR$a$, $a$Tú al humilde levantaras, Al débil tu fuerzas le$a$, $a$A|La$a$, $a$[{"id": "4fe2442f-7f6c-d365-df5b-cb0307c0e27f", "paragraph": "Tú al humilde levantaras,\nAl débil tu fuerzas le das.\nNuestras heridas sanaras,\nVida nos das.", "chorusPos": [[1]]}, {"id": "00da77a0-7ff9-7b3e-e5fc-5a355a501617", "paragraph": "Al que o cree lo llamas tu,\nPara decirle mío eres tú.\nAl orgulloso llamas y al infeliz,\nVengan a mi.", "chorusPos": [[1], [2]]}, {"id": "ee6ece23-6953-e064-1859-db3f6f7d8edd", "paragraph": "//Nos llamas, nos llamas, nos llamas\nhacia Cruz//.", "chorusPos": [[1], [2]]}, {"id": "e57dbf22-124e-55ca-029f-f8080b009d30", "paragraph": "//Nos llamas, nos llamas, nos llamas\nhacia Cruz//.", "chorusPos": [[0]]}]$a$::jsonb, $a$[{"choir": "El mismo que trae libertad.\nEl mismo amor que al ciego vista da.\nNos llamas con nombre hoy.\nTu nos llamas por nombre hoy.\n\nEl mismo Dios que los cielos formo.\nEl mismo Dios que en la cruz murió.\nNos llama con nombre hoy.\nTu nos llamas por nombre hoy.", "id": "e47f3bae-b9c2-219c-5574-c5a18e5a1593"}, {"choir": "//Oohh..... Oohh... oohh...//", "id": "dc17c1ae-f11e-0559-cd71-15ffa6c38e47"}]$a$::jsonb, $a$EL MISMO AMOR.json$a$),
('e8baa8a5-6dca-6678-6170-a0c6e6fe7dbf', $a$Salmos 19 - La Ley de Jehova$a$, $a$La ley de Jehová es perfecta,         que convie$a$, $a$C|Do$a$, $a$[{"id": "37af71ea-9f96-fa70-c851-43d744e8d909", "paragraph": "La ley de Jehová es perfecta,\n        que convierte el alma;\n        El testimonio de Jehová es fiel,\n        que hace sabio al sencillo.", "chorusPos": [[1]]}, {"id": "ab6a1f53-a7d8-28b7-b0c6-71a8402fd0b9", "paragraph": "Los mandamientos de Jehová son rectos,\n        que alegran el corazón;\n        El precepto de Jehová es puro,\n        que alumbra los ojos.", "chorusPos": [[1]]}, {"id": "8c8b92be-2295-34db-fc09-2f571d62a507", "paragraph": "El temor de Jehová es limpio,\n        que permanece para siempre;\n        Los juicios de Jehová son verdad,\n        todos justos.", "chorusPos": [[1]]}]$a$::jsonb, $a$[{"choir": "Deseables son más que el oro,\n        y más que mucho oro afinado;\n        y dulces más que la miel,\n        la que destila del panal.", "id": "85d944f8-64f6-6f05-b892-50ae33e12509"}]$a$::jsonb, $a$Salmos 19 - La Ley de Jehova.json$a$),
('59ae71c2-f07d-3c55-dd52-155d78aeb31f', $a$SUBLIME GRACIA$a$, $a$Sublime gracia del Señor que aun infeliz salvo. $a$, $a$C|Do$a$, $a$[{"id": "2803797f-f4bf-3343-6308-3cb9c9432bbc", "paragraph": "Sublime gracia del Señor que aun infeliz salvo.\nFui ciego mas hoy veo yo,\nPerdido y Él me hallo.", "chorusPos": [[0]]}, {"id": "9e1b0f00-76c9-d78a-3855-ca70ed9e43c8", "paragraph": "Su gracia me enseñó a temer,\nmis dudas ahuyento.\nOhh cuan precioso fue a mis ser,\nCuando él me transformo.", "chorusPos": [[1]]}, {"id": "d2375c32-d858-cd60-5da9-093701dae493", "paragraph": "En los peligros o aflicción,\nque yo he tenido aquí.\nSu gracia siempre me libro,\nY me guiara feliz.", "chorusPos": [[1]]}, {"id": "8404208d-cb78-ec72-2277-2d6a85d6bfcb", "paragraph": "Y cuando en Sion por siglos mil,\nBrillante este cual sol.\nY aun cantare por siempre aquí\nSu amor que me salvo.", "chorusPos": [[2]]}]$a$::jsonb, $a$[{"choir": "Ya libre soy Dios me salvo,\n        Y mis cadenas ya Él rompió\n        Y como un rio fluye el perdón\n        Sublime gracia inmenso amor.", "id": "4e1b8d53-f144-62cd-4a6e-844442c7f8eb"}, {"choir": "/Ya libre soy Dios me salvo,\n          Y mis cadenas ya Él rompió\n          Y como un rio fluye el perdón\n          Sublime gracia inmenso amor./", "id": "ac490b0f-cad6-071b-9022-567aa7eb1e68"}]$a$::jsonb, $a$SUBLIME GRACIA.json$a$),
('17783967-a675-4ec9-9584-e9199c5e3858', $a$En Jesus me Esconderé$a$, $a$Al abrigo del Señor Altísimo,   h...$a$, $a$--$a$, $a$[{"paragraph": "Al abrigo del Señor Altísimo, \n habitaré, \n A la sombra del omnipotente Rey,  \n descansaré."}, {"paragraph": "Si la enfermedad acecha,  \n si hay plaga por doquier. \n Firme en Sus promesas estaré, \n en Jesús me esconderé."}, {"paragraph": "En Ti confío Dios,  \n poderoso Emanuel. \n En Ti está mi fe,  \n en Jesús me esconderé."}, {"paragraph": "A la voz del Salvador  \n Sus ángeles, me cuidarán.  \n Con Su mano soberana  \n al tropezar, me sostendrá."}, {"paragraph": "En Sus alas de refugio \n mis temores rendiré. \n Me rodea Su fidelidad,  \n en Jesús me esconderé."}, {"paragraph": "En Ti confío Dios,  \n poderoso Emanuel. \n En Ti está mi fe,  \n en Jesús me esconderé."}, {"paragraph": "Aunque miles caigan junto a mí \n y muerte pueda ver. \n La maldad no vencerá  \n mientras Jesús conmigo esté."}, {"paragraph": "/Porque Él ha resucitado,  \n el morir no temeré./ \n Mientras viva y por la eternidad, \n en Jesús me esconderé."}, {"paragraph": "/En Ti confío Dios,  \n poderoso Emanuel. \n En Ti está mi fe,  \n en Jesús me esconderé./"}]$a$::jsonb, $a$[]$a$::jsonb, $a$En Jesus me Esconderé.json$a$),
('fe05a778-6506-2da7-631a-c1338c232fe8', $a$SI TE TENGO$a$, $a$No hay nada para mí que sea mejor, Que conocerte$a$, $a$G|Sol$a$, $a$[{"id": "488f1d7c-476b-a4e9-e9d8-11c51984b71c", "paragraph": "No hay nada para mí que sea mejor,\nQue conocerte, mi Jesús.\nPues en Tí encuentro paz ́, Y el amor,\nQue me has dado en la cruz.\nPor eso yo quiero cantar.", "chorusPos": [[1]]}, {"id": "0028fca1-bba8-0159-c428-9124ead01a1d", "paragraph": "Puedo amarte por que Tú Me amaste a mí,\nSiendo yo un pecador.\nNo merecía Tu perdón Menos aún,\nSer llamado hijo de Dios.\nPor eso yo quiero cantar.", "chorusPos": [[1]]}]$a$::jsonb, $a$[{"choir": "Eres todo lo que anhelo,\nTu voluntad es lo que quiero.\nTú satisfaces mi vida entera,\nTú, mi porción y mi roca eterna.\nLo que yo tengo lo doy por perdido,\nSi te tengo a Ti.", "id": "251db946-ae87-aeff-0add-55a76c54647b"}]$a$::jsonb, $a$SI TE TENGO.json$a$),
('7b3fbae3-a6dc-4a38-bff8-0cb44a63dc68', $a$Amémonos hermanos de todo corazón una familia somos$a$, $a$Amémonos hermanos de todo corazón...$a$, $a$--$a$, $a$[{"paragraph": "Amémonos hermanos de todo corazón una familia somos en nuestro padre dios \n el señor Jesucristo nos ha dejado un mandamiento nuevo  \n primero es el amor \n amemonos.... \n Aunque vengan tempestade nada tamas hoy hermanod esfuersate  \n cuando venga jesucristo aus gloria NO llevara \n falta poco para y a la se \n nuestra lucah se termina \n con crsito en su morda ya no habra mas sufirmeitop"}]$a$::jsonb, $a$[]$a$::jsonb, $a$Amémonos hermanos de todo corazón una familia somos.json$a$),
('d1d64942-aee2-4098-9b78-fada74220ba5', $a$De la misma iglesia$a$, $a$De la misma   Iglesia tú eres    ...$a$, $a$--$a$, $a$[{"paragraph": "De la misma \n Iglesia tú eres  \n si detrás del \n  calvario tú estás"}, {"paragraph": "si tú corazón  \n es como el mío \n dame la mano y  \n mi hermano serás"}, {"paragraph": "/Dame la mano, \n Querido hermano \n dame la mano  \n  mi hermano serás/"}]$a$::jsonb, $a$[]$a$::jsonb, $a$De la misma iglesia.json$a$),
('5f020110-0ba0-daaa-5f8b-f51b55672fa2', $a$10.000 RAZONES$a$, $a$[C]Que todo lo que soy [F]alabe al Señor,   [G]c$a$, $a$C|Do$a$, $a$[{"paragraph": "[C]Que todo lo que soy [F]alabe al Señor, \n [G]con todo mi [C]corazón. \n [F]De Tu grande [G]amor, cantaré [Em]\n [Am]Tu nombre alabaré [F]. [G]"}, {"paragraph": "[C]Sale el Sol, es un [F]nuevo amanecer, \n [G]cantaré a ti [C]otra vez. \n [F]Sea lo que [G]venga, confiaré [Em]en ti, \n [Am]alabaré en el [F]anochecer [G]."}, {"paragraph": "[C]Que todo lo que soy [F]alabe al Señor, \n [G]con todo mi [C]corazón. \n [F]De Tu grande [G]amor, cantaré, [Em]\n [Am]Tu nombre alabaré [F]. [G]"}, {"paragraph": "[C]Tu amor no tiene [F]fin y Tú eres [G]para siempre, \n [C]y bondadoso es [F]Tu corazón [G]. \n [Em]Por todo lo que [Am]has hecho, yo sigo [F]cantando, \n [C]10.000 razones [G]para alabar [C]."}, {"paragraph": "[C]Que todo lo que soy [F]alabe al Señor, \n [G]con todo mi [C]corazón. \n [F]De Tu grande [G]amor, cantaré [Em]\n [Am]Tu nombre alabaré [F]. [G]"}, {"paragraph": "[Am]Y en ese día, cuando [F]ya no tenga [G]fuerza, \n [Em]y se acerque Tu [Am]gloria. \n [F]Mi alma cantará [G]de tu amor sin [Em]final, \n [Am]10.000 años y [F]para siempre [G]más [C]."}, {"paragraph": "[C]Que todo lo que soy [F]alabe al Señor, \n [G]con todo mi [C]corazón. \n [F]De Tu grande [G]amor, cantaré \n [Am]/Tu nombre alabaré./ [F][G][C]"}]$a$::jsonb, $a$[]$a$::jsonb, $a$10.000 Razones.json$a$),
('947fcfc6-d732-fa7a-9e0c-026c9f8558a3', $a$CONTEMPLA A DIOS$a$, $a$¿Quién formó las olas al hablar?, ¿Quién contó l$a$, $a$C|Do$a$, $a$[{"id": "28a32dea-1203-984f-7446-8d5b642568ac", "paragraph": "¿Quién formó las olas al hablar?,\n¿Quién contó la arena en el mar?\nReyes, pueblos, tiemblan a su voz,\nla creación le rinde adoración.", "chorusPos": [[2]]}, {"id": "3eb8453e-5e2f-6e88-4d95-32bd1a42469c", "paragraph": "¿Quién le dio consejo al Señor?,\n¿Quién cuestiona lo que Él habló?\nQuién al sabio Dios puede enseñar,\n¿Quién comprende su gran majestad?", "chorusPos": [[2]]}, {"id": "92ad8b90-3ed9-4d52-6087-75a69475312d", "paragraph": "¿Quién sufrió los clavos en dolor?\n¿Quién llevo el mal del pecador?\nJesucristo, humilde al perecer,\nHa triunfado y reina con poder.", "chorusPos": [[2]]}, {"id": "0e7856ee-23c5-0c10-01bc-b409b9a9c96f", "paragraph": "", "chorusPos": [[1], [2]]}]$a$::jsonb, $a$[{"choir": "//¡Reinaras por siempre!//\n//¡Que tu gloria brille hoy!//", "id": "366284fd-9fb2-92c8-acc8-ddafa728b212"}, {"choir": "Contempla a Dios, en su trono está venid y adoradle.\nContempla al Rey, nadie es como Él venid y adoradle.", "id": "d99a0ab5-8c18-9106-af1e-d0b8b90ad2cb"}]$a$::jsonb, $a$Contempla a Dios.json$a$),
('c1656a97-eccd-f3f4-f4c0-58a5d58c18cc', $a$GLORIFICATE$a$, $a$Que toda nación te adore, Que toda la tierra cla$a$, $a$_$a$, $a$[{"id": "107e63ee-8cbb-f190-4f3f-dda08da9bcad", "paragraph": "Que toda nación te adore,\nQue toda la tierra clame a ti.\nQue todos tus santos canten;\n¡Santo es el Señor!", "chorusPos": [[0]]}, {"id": "7378098b-13ea-54a8-2571-ad647b7f875a", "paragraph": "Declaramos tu grandeza,\nlos cielos cuentan Tu gloria Dios\ny tus redimidos cantan\n¡Santo!, ¡Santo!", "chorusPos": [[1]]}, {"id": "ae40d2af-d0a5-624b-b2e0-a80f64a1c889", "paragraph": "Que toda nación te adore,\nQue toda la tierra clame a ti.\nQue todos tus santos canten;\n¡Santo es el Señor!", "chorusPos": [[0]]}, {"id": "90818fc3-84a9-6fb7-bc99-2c566d70dba5", "paragraph": "Declaramos tu grandeza,\nLos cielos cuentan tu gloria oh Dios\ny tus redimidos cantan\n¡Santo!, ¡Santo", "chorusPos": [[2]]}, {"id": "d32f3376-f45f-1a4b-c847-511fe59b4000", "paragraph": "/¡Aleluya! te damos gloria vivimos para ti./", "chorusPos": [[3]]}]$a$::jsonb, $a$[{"choir": "Al cantar abre los cielos\nY haz llover, muestra tu gloria,\nTe queremos ver\nY al adorarte, exáltate\nGlorifícate.", "id": "f5bea8f4-52b6-dfb0-20be-999be6f9215c"}, {"choir": "Al cantar abre los cielos\nY haz llover, muestra tu gloria,\nTe queremos ver\nY al adorarte, exáltate\n/Glorifícate/", "id": "6702afc2-03ba-cd7a-caf7-e87b099788ad"}, {"choir": "//Glorifícate\nAbre los cielos\nY haz llover,\nMuestra tu gloria\nTe queremos ver\nY al adorarte, exáltate//\n\n//Glorifícate//", "id": "400c701b-0669-59a9-8432-9c24702f508b"}]$a$::jsonb, $a$GLORIFICATE.json$a$),
('88f9c41e-6a62-45f9-a4ca-5b6bfa650a91', $a$Eres tu la única razón de mi adoración$a$, $a$ERES TU LA ÚNICA RAZÓN DE MI ADOR...$a$, $a$--$a$, $a$[{"paragraph": "ERES TU LA ÚNICA RAZÓN DE MI ADORACIÓN OH JESÚS  \n ERES TU LA ESPERANZA QUE ANHELE TENER OH JESÚS"}, {"paragraph": "CONFIE EN TI Y ME HAS AYUDADO \n TU SALVACION ME HAS REGALADO \n HOY HAY GOZO EN MI CORAZON  \n CON MI CANTO TE ALABARE"}, {"paragraph": "/TE ALABARE, TE GLORIFICARE \n TE ALABARE MI BUEN JESUS/ \n EN TODO TIEMPO  \n TE ALABARE  \n EN TODO TIEMPO  \n TE ADORARE  \n \t\t\t//TE ALABARE//"}]$a$::jsonb, $a$[]$a$::jsonb, $a$Eres tu la única razón de mi adoración.json$a$),
('6c4d3d5c-5472-11f5-f8e3-0a50e997443c', $a$ÈL ES CRISTO$a$, $a$Quién ayuda al herido Sana todo dolor Permanece $a$, $a$_$a$, $a$[{"id": "8d00ea1d-8711-fe71-2333-b6bc0eca95cc", "paragraph": "Quién ayuda al herido\nSana todo dolor\nPermanece por siempre\nDa descanso en su amor\nÉl es cristo.\nÉl es cristo\nNuestro salvador.\nÉl es cristo\nNo hay otro nombre solo Cristo", "chorusPos": [[0]]}, {"id": "3ecb0f83-32f0-11f0-e70f-1a718290364f", "paragraph": "Quién llevó nuestras cargas\nCambia el llanto en canción\nDio su vida en la cruz\nPara darnos perdón\nÉl es cristo\nÉl es cristo\nNuestro salvador\nÉl es cristo\nÉl es cristo\nRey por siempre\nNuestro redentor", "chorusPos": [[0]]}, {"id": "884b50e9-76b1-972a-947f-e197e2938a7a", "paragraph": "Él es cristo\nQuién moriría por un ladrón\nY tomaría mi lugar\nTodo el precio pago\n// Libres somos el venció //\nEl venció Libre somos\n\n//// No hay otro nombre solo cristo\nNo hay otra vida vivimos por él\nTodo el mal está vencido\n/ Tu reinas señor / ////\n\n/ Él es cristo /\nNuestro salvador\n/ Él es cristo /\nRey por siempre\nNuestro redentor\nÉl es cristo", "chorusPos": [[0]]}]$a$::jsonb, $a$[]$a$::jsonb, $a$ÈL ES CRISTO.json$a$),
('6c45f6eb-daf5-4c6c-9cae-4dee62067c1e', $a$HASTA LOS RIOS ALABAN TU NOMGRE$a$, $a$//Hasta los ríos alaban Tú nombre...$a$, $a$--$a$, $a$[{"paragraph": "//Hasta los ríos alaban Tú nombre// \n Mi bendito Cristo \n //Asi lo mismo quiero alabarte//"}, {"paragraph": "Quiero alabarte con estas mis manos \n Quiero alabarte con este mi cuerpo \n Mi bendito Criso"}]$a$::jsonb, $a$[]$a$::jsonb, $a$HASTA LOS RIOS ALABAN TU NOMGRE.json$a$),
('bc65fcf0-60cb-4d75-8765-da21c9744af8', $a$EL HOMBRE DE GALILEA$a$, $a$GALILEA    VA PASANDO YA//   //DE...$a$, $a$--$a$, $a$[{"paragraph": "GALILEA  \n VA PASANDO YA// \n //DEJALO QUE TE TOQUE// \n  Y TE DE SU BENDICION"}, {"paragraph": "//EL HOMBRE DE"}, {"paragraph": "GALILEA  \n VA PASANDO AQUI// \n //DEJALO QUE TE TOQUE// \n  Y TE DE SU BENDICION"}]$a$::jsonb, $a$[]$a$::jsonb, $a$EL HOMBRE DE GALILEA.json$a$),
('15a9ab4e-7572-bad3-4db2-210aca8d3c05', $a$ANTE EL TRONO CELESTIAL$a$, $a$Ante el trono celestial Él intercede hoy por mí $a$, $a$C/D|Do-Re$a$, $a$[{"id": "c523100f-be39-be89-415b-ea33f3adcc6f", "paragraph": "Ante el trono celestial\nÉl intercede hoy por mí\nGran Sacerdote es Jesús\nQuien por siempre vivirá", "chorusPos": [[1]]}, {"id": "61dfe5b1-a86c-60e4-d42c-d0e07b6129d0", "paragraph": "Cuando he caído en tentación\nY al sentir condenación\nAl ver al cielo encontraré\nAl inocente quien murió.", "chorusPos": [[2]]}, {"id": "02dc7fd4-e32e-d20f-5e86-bf82abce9408", "paragraph": "Ante el Cordero Redentor\nQuién al morir resucitó\nEl inmutable gran Yo Soy\nEl Rey de gloria y majestad", "chorusPos": [[3]]}]$a$::jsonb, $a$[{"choir": "Y en Sus manos por Su amor\nMi nombre ya grabado está\nY mientras en el cielo esté\n/ Nadie de Él me apartará /", "id": "32e31207-bd59-e62d-9665-d249cfaf0063"}, {"choir": "Y por su muerte el Salvador\nYa mi pecado perdonó\nPues Dios, el Justo, aceptó\n/ Su sacrificio hecho por mí /", "id": "62f1cc91-2ad2-b73e-aa96-b7671cb1de43"}, {"choir": "/ Unido a Él no moriré\nPues con Su sangre me compró\nMi vida escondida está\nEn Cristo Dios, mi Salvador/\n\n/En Cristo Dios, mi Salvador/", "id": "400f9e28-1fbf-d2e7-fb40-3b76a3dd147d"}]$a$::jsonb, $a$ANTE EL TRONO CELESTIAL.json$a$),
('0a04e4a0-76bd-4a1d-9462-330c27c2a054', $a$CANTA AL SENOR$a$, $a$CANTA  AL SENOR   M Cristo m rey ...$a$, $a$--$a$, $a$[{"paragraph": "CANTA  AL SENOR \n M Cristo m rey  \n No hay nade como tu \n Toda m vida quiero exaltar \n Las maravillas de tu amor"}, {"paragraph": "Consuelo, refugio  torre de fuerza y poder \n Todo m ser , lo que yo soy \n Nunca cese de adorar"}, {"paragraph": "Canta al señor, la creación  cantare \n La majestad y el poder sean a el \n Montes caerán  y el mar crujirá al sonar de tu nombre."}, {"paragraph": "Canto con gozo al mirar tu poder \n Siempre yo te amare y diré  \n incomparables promesa yo tengo en t"}]$a$::jsonb, $a$[]$a$::jsonb, $a$CANTA AL SENOR.json$a$),
('68e4ad5c-50e5-4d56-9306-504cfc450f6f', $a$COMO LAS ÁGUILAS$a$, $a$TU ME DAS LA FUERZA O DIOS    CAM...$a$, $a$--$a$, $a$[{"paragraph": "TU ME DAS LA FUERZA O DIOS  \n CAMINARE POR TI Y NO ME FATIGARE"}, {"paragraph": "AHORA QUE SOY JOVEN YO QUIERO BUSCARTE DE CORAZÓN  \n LO QUE ME OFRECE EL MUNDO NO QUIERO  \n ME DECLARO LIBRE, LIBRE PARA TI SEÑOR"}]$a$::jsonb, $a$[]$a$::jsonb, $a$COMO LAS ÁGUILAS.json$a$),
('3da09f4a-8aa6-4b59-b992-321bc8881c71', $a$DIOS DE MARAVILLAS$a$, $a$Todo lo creaste, la tierra cielo ...$a$, $a$--$a$, $a$[{"paragraph": "Todo lo creaste, la tierra cielo y mar. \n Los cielos son tu tabernáculo, Gloria al Dios altísimo."}, {"paragraph": "Dios del cielo maravilloso Dios, eres Santo, Santo. \n La creación muestra su majestad, eres Santo, Santo. \n //Dios de la creación. //"}, {"paragraph": "Cuando amanezco, he de celebrar tu luz. \n Si tropiezo en tinieblas, volveré a ver tu Cruz. \n //Dios del cielo maravilloso Dios, eres Santo, Santo. \n La creación muestra su majestad, eres Santo, Santo//"}, {"paragraph": "//Dios de la creación.// ALELUYA \n //Al Dios de la creación//"}, {"paragraph": "Dios del cielo maravilloso Dios, eres Santo, Santo. \n Muéstrame Señor tu corazón, eres Santo, Santo, Santo. \n //Dios de la creación. // ALELUYA. \n //Al Dios de la creación//"}]$a$::jsonb, $a$[]$a$::jsonb, $a$DIOS DE MARAVILLAS.json$a$),
('d2e65938-1ea0-637d-f37e-ab83e0864274', $a$YAHWEH$a$, $a$Con tu palabra el mundo afirmaste Señor. Tú alie$a$, $a$_$a$, $a$[{"id": "af3ffba5-526e-d52d-4ae9-bcb1121e5e32", "paragraph": "Con tu palabra el mundo afirmaste Señor.\nTú aliento de vida;\ndel polvo la humanidad formó.\nDespliegas tu nombre, y gloria en toda la creación.\nSANTO DIOS, SANTO DIOS.\n\nAun cuando el pecado, tu creación corrompió.\nEn tú fidelidad nos prometiste redención.\nun plan soberano por gracia y justicia mostró\nSANTO DIOS, SANTO DIOS\n\nSiempre guardas tus palabras, siempre\ncumples tus promesas.\nPor amor de tu nombre; Santo nombre.", "chorusPos": [[1]]}, {"id": "943c1bcd-32a0-0775-19e2-d70b7bc896d7", "paragraph": "En tiempo preciso el verbo carne se hizo.\nA que por bien esperamos,\nEl prometido en el principio.\nY vimos tu rostro llena de gracia y verdad.\nEn Jesús hijo de Dios SANTO DIOS.", "chorusPos": [[1]]}, {"id": "48f2a351-4368-c457-999b-032b106c76ef", "paragraph": "Nos aferramos a tus palabras,\nY creemos en tus promesas,\nY adoramos hoy tu nombre;\nSANTO NOMBRE.", "chorusPos": [[1], [2]]}]$a$::jsonb, $a$[{"choir": "YAHWEH, YAHWEH.\nPoderoso, Dios eterno ,verdadero.\n¿Ohh quién es como tú?\n\nYAHWEH, YAHWEH.\nTú nombre permanecerá para siempre\nOhhh YAHWEH", "id": "85fbe665-87b2-0c64-c00a-c23f83e533c1"}, {"choir": "YAHWEH ES TU NOMBRE :YAHWEH.\nOhhh ¡YAHWEH!", "id": "4be8c61b-d567-5b29-74be-262bfd6b1a23"}]$a$::jsonb, $a$YAHWEH.json$a$),
('1f8f344e-538d-46ae-a621-3bfb72068f77', $a$dame esos montes$a$, $a$Que a vivado mis sueños y mis van...$a$, $a$--$a$, $a$[{"paragraph": "Que a vivado mis sueños y mis vanidades las deje  \n dame esos montes y con mis fuerzas las hare cumplire la promesa yo e sido creado que  \n no habra gigante que me haga dudar \n y mi bandera eh de alzar \n hay quienes aconsejan que toque  ahora la retirada que lo aque se ahze en joven el viejo"}, {"paragraph": "que ya no digas"}]$a$::jsonb, $a$[]$a$::jsonb, $a$dame esos montes.json$a$)
